if(!defined('ABSPATH')){exit;}
final class Orion_Semantic_Product_Planner{
 private Orion_Product_Search $products;public function __construct(Orion_Product_Search $products){$this->products=$products;}
 public function recommend(array $classification,array $state,array $settings):array{$plan=$classification['search_plan']??array();if(!$plan)return array('products'=>array(),'missing_roles'=>array(),'plan'=>array(),'diagnostic'=>array('status'=>'no_search_plan'));$groups=array();$candidate_ids=array();foreach(array_slice($plan,0,10)as$item){$role=sanitize_key($item['role']??'');if($role==='')continue;$found=$this->products->search(array('query'=>$item['query'],'role'=>$role,'requirements'=>$item['requirements']??array(),'in_stock'=>true,'limit'=>12));$compact=array();foreach($found as$product){$id=(int)($product['id']??0);if(!$id)continue;$candidate_ids[$role][$id]=true;$compact[]=array('id'=>$id,'name'=>$product['name'],'type'=>$product['type'],'price'=>$product['price_text'],'categories'=>$product['categories'],'attributes'=>$product['attributes'],'description'=>mb_substr((string)($product['description']??$product['short_description']),0,700),'stock'=>$product['stock_status'],'retrieval'=>$product['retrieval']??array());}$groups[]=array('role'=>$role,'required'=>!empty($item['required']),'requirements'=>$item['requirements']??array(),'candidates'=>$compact);}if(!$candidate_ids){$missing=array_column($groups,'role');return array('products'=>array(),'missing_roles'=>$missing,'plan'=>$groups,'diagnostic'=>array('status'=>'no_relevant_candidates'));}$provider=Orion_AI_Provider_Factory::create($settings,'selection');$prompt='Read the supplied candidate title, full description, categories and attributes, then select only supplied candidate IDs. Decide semantically rather than requiring exact query words. Match products to roles and requirements. Reject candidates whose supplied data contradicts or does not reasonably support the role. A roller sleeve may satisfy a roller role only as a partial accessory and the reason must say a compatible frame is required. The same product ID may fill multiple roles only when its supplied title or description explicitly identifies a set, kit or bundle whose stated contents satisfy those roles. Return JSON only: {"selections":[{"role":"...","product_id":123,"reason":"..."}],"missing_roles":["..."]}.';$result=$provider->chat(array(array('role'=>'system','content'=>$prompt),array('role'=>'user','content'=>wp_json_encode(array('state'=>$state,'groups'=>$groups)))));$data=!empty($result['ok'])?$this->decode((string)($result['message']['content']??'')):null;$selected=array();$selected_index=array();$selected_roles=array();$missing=array();if(is_array($data)){foreach(($data['selections']??array())as$choice){$role=sanitize_key((string)($choice['role']??''));$id=absint($choice['product_id']??0);if(!$role||!$id||empty($candidate_ids[$role][$id]))continue;$product=$this->products->get_product($id);if(!$product||empty($product['in_stock']))continue;if(isset($selected_index[$id])){if(!$this->is_bundle($product))continue;$index=$selected_index[$id];$selected[$index]['kit_roles'][]=$role;$selected[$index]['recommendation_reason'].=' '.sanitize_text_field((string)($choice['reason']??''));$selected_roles[]=$role;continue;}$product['kit_role']=$role;$product['kit_roles']=array($role);$product['recommendation_reason']=sanitize_text_field((string)($choice['reason']??''));$selected_index[$id]=count($selected);$selected[]=$product;$selected_roles[]=$role;}foreach(($data['missing_roles']??array())as$role)$missing[]=sanitize_key((string)$role);}foreach($groups as$group)if(!in_array($group['role'],$selected_roles,true))$missing[]=$group['role'];$diagnostic=!empty($result['ok'])?(is_array($data)?array('status'=>'ok','usage'=>$result['usage']??array(),'attempts'=>$result['attempts']??array(),'fallback_used'=>!empty($result['fallback_used'])):array('status'=>'invalid_selector_output')):array('status'=>'selector_provider_error','error'=>sanitize_text_field((string)($result['error']??'')));return array('products'=>array_slice($selected,0,(int)$settings['max_products']),'missing_roles'=>array_values(array_unique($missing)),'plan'=>$groups,'diagnostic'=>$diagnostic);}
 private function is_bundle(array $product):bool{$text=strtolower((string)($product['name']??'').' '.(string)($product['description']??''));return(bool)preg_match('/\b(set|kit|bundle|complete set)\b/',$text);}private function decode(string $text):?array{$text=trim(preg_replace('/^```(?:json)?\s*|\s*```$/i','',trim($text)));$data=json_decode($text,true);if(is_array($data))return$data;if(preg_match('/\{[\s\S]*\}/',$text,$m)){$data=json_decode($m[0],true);return is_array($data)?$data:null;}return null;}
}
